#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;
struct Nd{ int i; double x,y; int prev,next; };
// returns triangles string, plus stats
string sim(long long N, double*minA,double*maxA,int*fallback,long long*iters){
  *minA=1e300;*maxA=-1e300;*fallback=0;*iters=0;
  if(N<=0) return string();
  vector<double> px(N),py(N);
  for(long long i=0;i<N;i++){ double a=2.0*M_PI*(double)i/(double)N; px[i]=cos(a); py[i]=sin(a);}
  double s=0; for(long long i=0;i<N;i++){ long long j=(i-1+N)%N; s+=(px[j]-px[i])*(py[i]+py[j]); }
  vector<Nd> nd(N);
  // build in forward or reverse
  int last=-1;
  auto ins=[&](long long i){ nd[i].i=(int)i; nd[i].x=px[i]; nd[i].y=py[i];
     if(last<0){ nd[i].prev=(int)i; nd[i].next=(int)i; }
     else { nd[i].next=nd[last].next; nd[i].prev=last; nd[nd[last].next].prev=(int)i; nd[last].next=(int)i; }
     last=(int)i; };
  bool fwd = (true == (s>0));
  if(fwd) for(long long i=0;i<N;i++) ins(i); else for(long long i=N;i-->0;) ins(i);
  auto rm=[&](int a){ nd[nd[a].next].prev=nd[a].prev; nd[nd[a].prev].next=nd[a].next; };
  if(last>=0 && nd[last].x==nd[nd[last].next].x && nd[last].y==nd[nd[last].next].y){ rm(last); last=nd[last].next; }
  int outer=last;
  if(nd[outer].prev==nd[outer].next) return string();
  auto ar=[&](int p,int q,int r){ return (nd[q].y-nd[p].y)*(nd[r].x-nd[q].x)-(nd[q].x-nd[p].x)*(nd[r].y-nd[q].y); };
  string out; char buf[32];
  int ear=outer, stop=ear;
  while(nd[ear].prev!=nd[ear].next){
    (*iters)++;
    int prev=nd[ear].prev, nx=nd[ear].next;
    double a=ar(prev,ear,nx);
    if(a<*minA)*minA=a; if(a>*maxA)*maxA=a;
    if(a<0){
      snprintf(buf,32,"%d ",nd[prev].i); out+=buf;
      snprintf(buf,32,"%d ",nd[ear].i); out+=buf;
      snprintf(buf,32,"%d ",nd[nx].i); out+=buf;
      rm(ear); ear=nd[nx].next; stop=nd[nx].next; continue;
    }
    ear=nx;
    if(ear==stop){ *fallback=1; break; }
  }
  return out;
}
int main(int argc,char**argv){
  // arg: list of n values
  for(int k=1;k<argc;k++){
    long long n=atoll(argv[k]);
    // wrapping i32 3n
    int ni=(int)n; int N3=(int)((unsigned)ni*3u);
    double mn,mx; int fb; long long it;
    string got=sim(N3,&mn,&mx,&fb,&it);
    printf("%s\t%d\t%zu\tmin=%.6e\tmax=%.6e\tfb=%d\titers=%lld\n",argv[k],N3,got.size(),mn,mx,fb,it);
    FILE*f=fopen(("/tmp/an/out_"+string(argv[k])+".txt").c_str(),"w");
    fwrite(got.data(),1,got.size(),f); fclose(f);
  }
  return 0;
}
EOF
