#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <algorithm>
using namespace std;
static inline double ar(double px,double py,double qx,double qy,double rx,double ry){
  return (qy-py)*(rx-qx)-(qx-px)*(ry-qy);
}
int main(int argc,char**argv){
  for(int k=1;k<argc;k++){
    double Nd=atof(argv[k]); long long N=(long long)Nd;
    long long step = N>4000000 ? N/4000000 : 1; if(step<1) step=1;
    double worst=-1e300; long long wi=-1; long long nonneg=0;
    // scan triples i-1,i,i+1
    for(long long i=0;i<N;i+=step){
      long long a=(i-1+N)%N, b=i, c=(i+1)%N;
      double aa=2.0*M_PI*(double)a/(double)N, ab=2.0*M_PI*(double)b/(double)N, ac=2.0*M_PI*(double)c/(double)N;
      double v=ar(cos(aa),sin(aa),cos(ab),sin(ab),cos(ac),sin(ac));
      if(v>=0) nonneg++;
      if(v>worst){worst=v;wi=i;}
    }
    double d=2*M_PI/(double)N;
    double ideal=-4.0*sin(d/2)*sin(d/2)*sin(d);
    printf("N=%-12lld step=%-8lld delta=%.5e ideal_area=%.6e worst_fl=%.6e  ratio=%.4f  nonneg=%lld (at i=%lld)\n",
        N,step,d,ideal,worst, worst/ideal, nonneg, wi);
  }
}
EOF
