#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <vector>
using namespace std;
int main(int argc,char**argv){
  long long LO=atoll(argv[1]), HI=atoll(argv[2]);
  vector<double> px,py; vector<int> pr,nx;
  long long fbcount=0, dupcount=0, badcount=0; double worstmax=-1e300; long long worstN=0;
  for(long long N=LO;N<=HI;N++){
    px.resize(N);py.resize(N);pr.resize(N);nx.resize(N);
    for(long long i=0;i<N;i++){double a=2.0*M_PI*(double)i/(double)N; px[i]=cos(a);py[i]=sin(a);}
    // adjacent exact-equality check
    for(long long i=0;i<N;i++){long long j=(i+1)%N; if(N>1&&px[i]==px[j]&&py[i]==py[j]){dupcount++; printf("DUP N=%lld i=%lld\n",N,i); break;}}
    if(N<3){continue;}
    for(long long i=0;i<N;i++){pr[i]=(int)((i-1+N)%N); nx[i]=(int)((i+1)%N);}
    long long tri=0; int ear=(int)(N-1), stop=ear; int fb=0; double wm=-1e300;
    while(pr[ear]!=nx[ear]){
      int p=pr[ear], q=nx[ear];
      double a=(py[ear]-py[p])*(px[q]-px[ear])-(px[ear]-px[p])*(py[q]-py[ear]);
      if(a>wm)wm=a;
      if(a<0){ tri++; nx[p]=q; pr[q]=p; ear=nx[q]; stop=nx[q]; continue; }
      ear=q; if(ear==stop){fb=1;break;}
    }
    if(fb){fbcount++; if(fbcount<6) printf("FALLBACK N=%lld\n",N);}
    if(tri!=N-2){badcount++; if(badcount<6) printf("TRI N=%lld tri=%lld expect=%lld\n",N,tri,N-2);}
    if(wm>worstmax){worstmax=wm;worstN=N;}
  }
  printf("range [%lld,%lld]: fallbacks=%lld dups=%lld tricount_anomalies=%lld  worst_area=%.6e at N=%lld\n",LO,HI,fbcount,dupcount,badcount,worstmax,worstN);
}
EOF
