int main(int argc,char**argv){
  long long N=atoll(argv[1]);
  vector<double> px(N),py(N); vector<int> pr(N),nx(N);
  for(long long i=0;i<N;i++){double a=2.0*M_PI*(double)i/(double)N;px[i]=cos(a);py[i]=sin(a);pr[i]=(int)((i-1+N)%N);nx[i]=(int)((i+1)%N);}
  auto pit=[&](int a,int b,int c,int p){
    return (px[c]-px[p])*(py[a]-py[p])-(px[a]-px[p])*(py[c]-py[p])>=0 &&
           (px[a]-px[p])*(py[b]-py[p])-(px[b]-px[p])*(py[a]-py[p])>=0 &&
           (px[b]-px[p])*(py[c]-py[p])-(px[c]-px[p])*(py[b]-py[p])>=0; };
  long long tri=0, work=0; int ear=(int)(N-1), stop=ear;
  while(pr[ear]!=nx[ear]){
    int a=pr[ear],b=ear,c=nx[ear];
    double ap=(py[b]-py[a])*(px[c]-px[b])-(px[b]-px[a])*(py[c]-py[b]);
    bool isear = ap<0;
    if(isear){ int p=nx[nx[ear]]; while(p!=pr[ear]){ work++; double ar2=(py[p]-py[pr[p]])*(px[nx[p]]-px[p])-(px[p]-px[pr[p]])*(py[nx[p]]-py[p]); if(pit(a,b,c,p)&&ar2>=0){isear=false;break;} p=nx[p]; } }
    if(isear){ tri++; nx[a]=c; pr[c]=a; ear=nx[c]; stop=nx[c]; continue; }
    ear=c; if(ear==stop) break;
  }
  printf("N=%lld tri=%lld inner_loop_iterations=%lld\n",N,tri,work);
}
